def test_get_authenticated_user_profile():
    url = f"{BASE_URL}/api/auth/perfil"
    headers = {
        "x-token": TOKEN,
        "Accept": "application/json"
    }
    try:
        resp = requests.get(url, headers=headers, timeout=30)
    except RequestException as e:
        raise AssertionError(f"Request to {url} failed: {e}") from e

    # Basic status code check
    if resp.status_code != 200:
        # Try to include error body for debugging
        try:
            err = resp.json()
        except Exception:
            err = resp.text
        raise AssertionError(f"Expected status 200 but got {resp.status_code}. Response: {err}")

    # Content-Type should be JSON
    ct = resp.headers.get("Content-Type", "")
    assert "application/json" in ct or ct.startswith("application/json"), f"Expected JSON response, got Content-Type: {ct}"

    try:
        body = resp.json()
    except ValueError as e:
        raise AssertionError(f"Response body is not valid JSON: {e}") from e

    # The API may return the user directly or wrapped in a 'usuario' field
    if isinstance(body, dict) and "usuario" in body:
        user = body["usuario"]
    else:
        user = body

    assert isinstance(user, dict), f"Expected user object (dict), got: {type(user)}"

    # Validate presence of key profile fields according to PRD: 'nombre' and 'email' should exist
    assert "nombre" in user, f"'nombre' not found in user profile: {user.keys()}"
    assert "email" in user, f"'email' not found in user profile: {user.keys()}"

    # Password should not be exposed
    assert "password" not in user, "Password must not be present in the profile response"

    # Optionally check role if present
    if "rol" in user:
        assert user["rol"] in ("admin", "usuario"), f"Unexpected rol value: {user['rol']}"

    print("TC003 passed: Authenticated user profile retrieved successfully.")

if __name__ == "__main__":
    try:
        test_get_authenticated_user_profile()
    except AssertionError as e:
        print(f"TC003 failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"TC003 encountered an unexpected error: {e}")
        sys.exit(2)
    sys.exit(0)

import requests
import uuid
import sys

BASE_URL = "http://localhost:3000"
TIMEOUT = 30

# Admin x-token provided by environment/authentication (from instructions)
ADMIN_X_TOKEN = "<ADMIN_JWT_REDACTED>"

def _extract_user(obj):
    if not isinstance(obj, dict):
        return None
    # Common shapes: { "usuario": { ... } } or { "token": "...", "usuario": { ... } } or direct user dict
    if "usuario" in obj and isinstance(obj["usuario"], dict):
        return obj["usuario"]
    # Some endpoints might return the user directly
    # Heuristics: presence of email or nombre fields
    if "email" in obj or "nombre" in obj:
        return obj
    return None

def _extract_user_id(user_obj):
    # Try common id fields
    for key in ("uid", "_id", "id"):
        if isinstance(user_obj, dict) and key in user_obj:
            return user_obj[key]
    return None

def test_put_api_auth_perfil_update_authenticated_user_profile():
    created_user_id = None
    admin_headers = {
        "Content-Type": "application/json",
        "x-token": ADMIN_X_TOKEN
    }

    # Create a new user to act as the authenticated subject
    unique = uuid.uuid4().hex[:8]
    register_payload = {
        "nombre": f"TestUser {unique}",
        "email": f"testuser+{unique}@example.com",
        "password": "Password1A"
    }

    try:
        resp = requests.post(f"{BASE_URL}/api/auth/registro", json=register_payload, headers={"Content-Type": "application/json"}, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Registration request failed: {e}")

    try:
        assert resp.status_code == 201, f"Expected 201 from registration, got {resp.status_code}, body: {resp.text}"
        resp_json = resp.json()
    except ValueError:
        raise AssertionError(f"Registration response is not valid JSON. Status: {resp.status_code}, Body: {resp.text}")

    # Extract token and user
    token = resp_json.get("token")
    user_obj = _extract_user(resp_json)
    assert token, f"Registration did not return token. Body: {resp_json}"
    assert user_obj is not None, f"Registration did not return usuario object. Body: {resp_json}"

    created_user_id = _extract_user_id(user_obj)
    # If we couldn't find an id in the returned usuario, try to decode from token? Skip deletion if not found.
    assert created_user_id is not None, f"Could not determine created user id from response usuario: {user_obj}"

    # Prepare update payload: change nombre and email
    new_unique = uuid.uuid4().hex[:6]
    update_payload = {
        "nombre": f"Updated {unique}",
        "email": f"updated+{new_unique}+{unique}@example.com"
    }

    user_headers = {
        "Content-Type": "application/json",
        "x-token": token
    }

    try:
        resp_update = requests.put(f"{BASE_URL}/api/auth/perfil", json=update_payload, headers=user_headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Update request failed: {e}")

    try:
        assert resp_update.status_code == 200, f"Expected 200 from perfil update, got {resp_update.status_code}, body: {resp_update.text}"
        update_json = resp_update.json()
    except ValueError:
        raise AssertionError(f"Update response is not valid JSON. Status: {resp_update.status_code}, Body: {resp_update.text}")

    updated_user = _extract_user(update_json)
    assert updated_user is not None, f"Update response did not contain user object. Body: {update_json}"

    # Validate fields updated
    assert updated_user.get("nombre") == update_payload["nombre"], f"Nombre not updated. Expected {update_payload['nombre']}, got {updated_user.get('nombre')}"
    assert updated_user.get("email") == update_payload["email"], f"Email not updated. Expected {update_payload['email']}, got {updated_user.get('email')}"

    # Optionally verify the id stayed the same
    updated_id = _extract_user_id(updated_user)
    assert updated_id == created_user_id, f"User id changed after update. Before: {created_user_id}, After: {updated_id}"

    print("TC004 passed: authenticated user profile updated successfully.")

    # Cleanup: delete created user using admin token
    try:
        del_resp = requests.delete(f"{BASE_URL}/api/usuarios/{created_user_id}", headers=admin_headers, timeout=TIMEOUT)
        # Expect 200 for successful logical delete
        if del_resp.status_code not in (200,):
            raise AssertionError(f"Cleanup deletion expected status 200, got {del_resp.status_code}, body: {del_resp.text}")
    except requests.RequestException as e:
        raise AssertionError(f"Cleanup deletion request failed: {e}")

if __name__ == "__main__":
    try:
        test_put_api_auth_perfil_update_authenticated_user_profile()
    except AssertionError as e:
        print("Test failed:", e)
        sys.exit(1)
    except Exception as e:
        print("Unexpected error during test:", e)
        sys.exit(2)
    sys.exit(0)

import requests
import uuid
import sys
import time

BASE_URL = "http://localhost:3000"
ADMIN_TOKEN = "<ADMIN_JWT_REDACTED>"
HEADERS = {
    "x-token": ADMIN_TOKEN,
    "Content-Type": "application/json"
}
TIMEOUT = 30


def test_get_api_usuarios_id_get_user_details_by_id():
    created_user_id = None
    try:
        # Create a new user to retrieve later
        unique_email = f"test.user.{uuid.uuid4().hex[:8]}@example.com"
        create_payload = {
            "nombre": "Test User",
            "email": unique_email,
            "password": "Str0ngPassw0rd",
            "rol": "usuario"
        }

        try:
            resp = requests.post(f"{BASE_URL}/api/usuarios", json=create_payload, headers=HEADERS, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise AssertionError(f"Failed to create user: {e}")

        assert resp is not None, "No response received when creating user"
        if resp.status_code != 201:
            # try to provide response body for debugging
            try:
                body = resp.json()
            except Exception:
                body = resp.text
            raise AssertionError(f"Expected 201 when creating user, got {resp.status_code}. Response: {body}")

        try:
            body = resp.json()
        except ValueError:
            raise AssertionError("Create user response is not valid JSON")

        # Response might be the user object directly or wrapped. Normalize.
        if isinstance(body, dict) and ("usuario" in body and isinstance(body["usuario"], dict)):
            created = body["usuario"]
        else:
            created = body

        created_user_id = created.get("_id") or created.get("id") or created.get("uid")
        assert created_user_id, f"Created user id not found in response: {created}"

        # Basic checks on created user
        assert created.get("email") == unique_email, f"Created user email mismatch: expected {unique_email}, got {created.get('email')}"
        assert created.get("nombre") == "Test User", f"Created user nombre mismatch: expected 'Test User', got {created.get('nombre')}"
        # rol may be present
        if "rol" in created:
            assert created["rol"] in ("usuario", "admin"), f"Unexpected rol value: {created.get('rol')}"

        # Now retrieve the user by id as admin
        try:
            get_resp = requests.get(f"{BASE_URL}/api/usuarios/{created_user_id}", headers=HEADERS, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise AssertionError(f"Failed to GET user by id: {e}")

        assert get_resp is not None, "No response received when retrieving user by id"
        if get_resp.status_code != 200:
            try:
                get_body = get_resp.json()
            except Exception:
                get_body = get_resp.text
            raise AssertionError(f"Expected 200 when retrieving user by id, got {get_resp.status_code}. Response: {get_body}")

        try:
            get_body = get_resp.json()
        except ValueError:
            raise AssertionError("Get user response is not valid JSON")

        if isinstance(get_body, dict) and ("usuario" in get_body and isinstance(get_body["usuario"], dict)):
            fetched = get_body["usuario"]
        else:
            fetched = get_body

        # Validate fetched fields
        fetched_id = fetched.get("_id") or fetched.get("id") or fetched.get("uid")
        assert fetched_id == created_user_id, f"Fetched user id ({fetched_id}) does not match created id ({created_user_id})"
        assert fetched.get("email") == unique_email, f"Fetched user email ({fetched.get('email')}) does not match expected ({unique_email})"
        assert fetched.get("nombre") == "Test User", f"Fetched user nombre ({fetched.get('nombre')}) does not match expected ('Test User')"
        # Active user expected
        if "estado" in fetched:
            assert fetched["estado"] is True or fetched["estado"] == "true", f"Expected usuario estado to be active, got {fetched.get('estado')}"

        print("TC007 passed: Admin retrieved active user details by id successfully.")

    finally:
        if created_user_id:
            try:
                del_resp = requests.delete(f"{BASE_URL}/api/usuarios/{created_user_id}", headers=HEADERS, timeout=TIMEOUT)
            except requests.RequestException as e:
                raise AssertionError(f"Failed to delete created user in cleanup: {e}")

            # Accept 200 as success; if already deleted or not found, it's an issue but cleanup should attempt to proceed
            if del_resp.status_code != 200:
                try:
                    del_body = del_resp.json()
                except Exception:
                    del_body = del_resp.text
                raise AssertionError(f"Expected 200 when deleting user in cleanup, got {del_resp.status_code}. Response: {del_body}")


if __name__ == "__main__":
    try:
        test_get_api_usuarios_id_get_user_details_by_id()
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(2)
    print("Test completed successfully.")

import requests
import uuid
import re
import sys

BASE_URL = "http://localhost:3000"
ADMIN_TOKEN = "<ADMIN_JWT_REDACTED>"
TIMEOUT = 30

def test_tc008_post_api_usuarios_create_new_user_by_admin():
    headers = {
        "Content-Type": "application/json",
        "x-token": ADMIN_TOKEN
    }

    unique_email = f"testuser_{uuid.uuid4().hex[:8]}@example.com"
    plain_password = "Password1A"  # meets typical policy: min 8, upper, lower, number
    payload = {
        "nombre": "Test User",
        "email": unique_email,
        "password": plain_password,
        "rol": "usuario"
    }

    created_user_id = None

    try:
        # Create user as admin
        try:
            resp = requests.post(f"{BASE_URL}/api/usuarios", json=payload, headers=headers, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise AssertionError(f"Request to create user failed: {e}")

        assert resp is not None, "No response received when creating user"
        assert resp.status_code == 201, f"Expected 201 Created, got {resp.status_code}: {resp.text}"

        try:
            user_obj = resp.json()
        except ValueError:
            raise AssertionError(f"Response is not valid JSON: {resp.text}")

        assert isinstance(user_obj, dict), f"Expected JSON object for created user, got: {type(user_obj)}"

        # Determine user id property
        if "uid" in user_obj:
            created_user_id = user_obj["uid"]
        elif "id" in user_obj:
            created_user_id = user_obj["id"]
        elif "_id" in user_obj:
            created_user_id = user_obj["_id"]
        else:
            # Try nested 'usuario' key (some APIs return { usuario: { ... } })
            if "usuario" in user_obj and isinstance(user_obj["usuario"], dict):
                nested = user_obj["usuario"]
                if "uid" in nested:
                    created_user_id = nested["uid"]
                elif "id" in nested:
                    created_user_id = nested["id"]
                elif "_id" in nested:
                    created_user_id = nested["_id"]
                else:
                    # if still no id, attempt to find any plausible id field
                    for k in ("_id", "id", "uid"):
                        if k in nested:
                            created_user_id = nested[k]
                            break
                user_obj = nested  # treat nested as the user object
            else:
                raise AssertionError(f"Created user object does not contain an id. Response: {user_obj}")

        # Basic checks on returned user fields
        assert user_obj.get("email") == unique_email, f"Returned user email mismatch: expected {unique_email}, got {user_obj.get('email')}"
        assert user_obj.get("nombre") == "Test User", f"Returned user nombre mismatch: expected 'Test User', got {user_obj.get('nombre')}"
        assert user_obj.get("rol") in ("usuario", "admin"), f"Returned user rol unexpected: {user_obj.get('rol')}"

        # Verify password handling: if password field is returned, it must be hashed (not equal to plain) and look like bcrypt
        if "password" in user_obj:
            returned_password = user_obj["password"]
            assert returned_password != plain_password, "Returned password matches plaintext; it should be hashed or not returned"
            # common bcrypt hash prefix $2a$, $2b$, $2y$
            assert re.match(r"^\$2[aby]\$[0-9]{2}\$.{53}$", returned_password) or returned_password.startswith("$2"), \
                f"Returned password does not match expected bcrypt pattern: {returned_password}"
        else:
            # If password is not returned (preferred), verify credentials by logging in with the created user
            login_payload = {"email": unique_email, "password": plain_password}
            try:
                login_resp = requests.post(f"{BASE_URL}/api/auth/login", json=login_payload, timeout=TIMEOUT)
            except requests.RequestException as e:
                raise AssertionError(f"Login request failed for created user: {e}")
            assert login_resp.status_code == 200, f"Login with created user failed, expected 200, got {login_resp.status_code}: {login_resp.text}"
            try:
                login_json = login_resp.json()
            except ValueError:
                raise AssertionError(f"Login response not JSON: {login_resp.text}")
            assert "token" in login_json and "usuario" in login_json, f"Login response missing token/usuario: {login_json}"

    finally:
        # Cleanup: delete created user if we have its id
        if created_user_id:
            try:
                del_resp = requests.delete(f"{BASE_URL}/api/usuarios/{created_user_id}", headers=headers, timeout=TIMEOUT)
            except requests.RequestException as e:
                # Can't raise in finally; print and exit non-zero
                print(f"Warning: failed to delete test user {created_user_id}: {e}", file=sys.stderr)
                raise
            # Acceptable deletion responses: 200 OK; if already deleted or not found, could be 404 but we assert 200 as expected
            assert del_resp.status_code == 200, f"Expected 200 on delete, got {del_resp.status_code}: {del_resp.text}"

if __name__ == "__main__":
    test_tc008_post_api_usuarios_create_new_user_by_admin()
    print("TC008 passed")
